window.IELTS.DATA.listening = [{"level":"A1","task":["Role-play the dialogue with a partner, changing the food and prices."],"title":"At the cafe","script":"Waiter: Good afternoon. What would you like?\nAigerim: Hello. I\u0027d like a cup of tea and a sandwich, please.\nWaiter: What kind of sandwich? We have cheese, chicken and egg.\nAigerim: Chicken, please. How much is it?\nWaiter: The tea is 300 tenge and the sandwich is 700 tenge. One thousand tenge in total.\nAigerim: Here you are. Can I sit by the window?\nWaiter: Of course. I\u0027ll bring your order in five minutes.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Waiter":"f","Aigerim":"m"},"tasks":[{"q":"What does Aigerim order to drink?","e":"Tea","a":"Tea"},{"q":"Which sandwich does she choose?","e":"Chicken","a":"Chicken"},{"q":"How much is the sandwich?","e":"700 tenge","a":"700 tenge"},{"q":"What is the total price?","e":"1000 tenge","a":"1000 tenge"},{"q":"Where does she want to sit?","e":"By the window","a":"By the window"}]},{"level":"A1","task":["Draw a map and give directions from your school to the nearest shop."],"title":"Asking for directions","script":"Tourist: Excuse me, how do I get to the museum?\nLocal: Go straight along this street for two blocks. Then turn left at the traffic lights.\nTourist: Is it far?\nLocal: No, it\u0027s about ten minutes on foot. The museum is next to the bank, opposite the park.\nTourist: Thank you very much!\nLocal: You\u0027re welcome. Have a nice day.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Tourist":"f","Local":"m"},"tasks":[{"q":"Where does the tourist want to go?","e":"To the museum","a":"To the museum"},{"q":"How many blocks should the tourist go straight?","e":"Two","a":"Two"},{"q":"Where must the tourist turn left?","e":"At the traffic lights","a":"At the traffic lights"},{"q":"How long does it take on foot?","e":"About ten minutes","a":"About ten minutes"},{"q":"What is the museum next to?","e":"The bank","a":"The bank"}]},{"level":"A1","task":["Prepare your own self-introduction of 6-8 sentences."],"title":"Introducing yourself","script":"Narrator: Hello, my name is Dana. I\u0027m fourteen years old. I live in Astana with my parents and my little brother. I go to school number 12. My favourite subjects are English and geography. In my free time I play volleyball and read books. I want to be a pilot.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How old is Dana?","e":"Fourteen","a":"Fourteen"},{"q":"Who does she live with?","e":"Her parents and little brother","a":"Her parents and little brother"},{"q":"What are her favourite subjects?","e":"English and geography","a":"English and geography"},{"q":"What sport does she play?","e":"Volleyball","a":"Volleyball"},{"q":"What does she want to be?","e":"A pilot","a":"A pilot"}]},{"level":"A1","task":["Write your own booking dialogue with a different room type."],"title":"Booking a hotel room","script":"Receptionist: Good morning, Grand Hotel. How can I help you?\nGuest: I\u0027d like to book a double room for three nights, from the 5th of June.\nReceptionist: Certainly. Would you like breakfast included?\nGuest: Yes, please. How much is it?\nReceptionist: It\u0027s 25,000 tenge per night with breakfast.\nGuest: That\u0027s fine. My name is Karim Sadykov.\nReceptionist: Thank you, Mr Sadykov. Your room is booked.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Receptionist":"f","Guest":"m"},"tasks":[{"q":"What kind of room does the guest want?","e":"A double room","a":"A double room"},{"q":"How many nights?","e":"Three","a":"Three"},{"q":"From which date?","e":"The 5th of June","a":"The 5th of June"},{"q":"Is breakfast included?","e":"Yes","a":"Yes"},{"q":"What is the price per night?","e":"25,000 tenge","a":"25,000 tenge"}]},{"level":"A1","task":["Invent a similar phone call and invite a friend to a different activity."],"title":"A phone call to a friend","script":"Dana: Hi, Aida! It\u0027s Dana. Are you free on Saturday?\nAida: Hi, Dana! Yes, I think so. What are you planning?\nDana: Let\u0027s go to the cinema. There is a new comedy at three o\u0027clock.\nAida: Sounds great! Where shall we meet?\nDana: At the entrance at half past two.\nAida: OK. See you on Saturday. Bye!","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Aida":"m","Dana":"f"},"tasks":[{"q":"Who is calling?","e":"Dana","a":"Dana"},{"q":"What do they plan to do?","e":"Go to the cinema","a":"Go to the cinema"},{"q":"What kind of film is it?","e":"A comedy","a":"A comedy"},{"q":"What time does the film start?","e":"Three o\u0027clock","a":"Three o\u0027clock"},{"q":"Where and when do they meet?","e":"At the entrance at half past two","a":"At the entrance at half past two"}]},{"level":"A1","task":["Role-play a visit to the doctor with your own symptoms."],"title":"At the doctor","script":"Doctor: Good morning. What\u0027s the matter?\nPatient: I have a sore throat and a headache.\nDoctor: How long have you been ill?\nPatient: Since Tuesday. I also have a high temperature.\nDoctor: Let me check. Open your mouth, please. You have a cold. Stay in bed, drink hot tea and take this medicine three times a day.\nPatient: Thank you, doctor.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Patient":"m","Doctor":"f"},"tasks":[{"q":"What are the patient\u0027s problems?","e":"A sore throat and a headache","a":"A sore throat and a headache"},{"q":"Since when has the patient been ill?","e":"Since Tuesday","a":"Since Tuesday"},{"q":"What is the doctor\u0027s diagnosis?","e":"A cold","a":"A cold"},{"q":"How many times a day should the patient take medicine?","e":"Three times","a":"Three times"},{"q":"What else should the patient do?","e":"Stay in bed and drink hot tea","a":"Stay in bed and drink hot tea"}]},{"level":"A1","task":["Role-play buying a bus ticket to another city."],"title":"Buying a ticket","script":"Passenger: Good morning. One ticket to Almaty, please.\nClerk: Single or return?\nPassenger: Return, please. I travel on Friday and come back on Sunday.\nClerk: The train leaves at 8:15 in the evening from platform 3. That is 15,000 tenge.\nPassenger: Can I pay by card?\nClerk: Yes, of course. Here is your ticket. Have a good trip!","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Passenger":"f","Clerk":"m"},"tasks":[{"q":"Where does the passenger want to go?","e":"To Almaty","a":"To Almaty"},{"q":"Is the ticket single or return?","e":"Return","a":"Return"},{"q":"What time does the train leave?","e":"8:15 in the evening","a":"8:15 in the evening"},{"q":"Which platform?","e":"Platform 3","a":"Platform 3"},{"q":"How does the passenger pay?","e":"By card","a":"By card"}]},{"level":"A1","task":["Write your own shopping list of eight things."],"title":"In the supermarket","script":"Mum: We need bread, milk and some apples.\nAli: Look, the apples are on sale today. One kilo is 400 tenge.\nMum: Good. Take two kilos. And please find a litre of milk.\nAli: Here it is. Do we need eggs?\nMum: Yes, ten eggs. Then we go to the cash desk.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Ali":"m","Mum":"f"},"tasks":[{"q":"What do they need to buy first?","e":"Bread, milk and apples","a":"Bread, milk and apples"},{"q":"How much is a kilo of apples?","e":"400 tenge","a":"400 tenge"},{"q":"How many kilos of apples do they take?","e":"Two","a":"Two"},{"q":"How many eggs do they need?","e":"Ten","a":"Ten"},{"q":"Where do they go at the end?","e":"To the cash desk","a":"To the cash desk"}]},{"level":"A2","task":["Tell a partner about your hobby in six sentences."],"title":"My favourite hobby","script":"Narrator: Hi, I\u0027m Marat. I\u0027m twelve and my favourite hobby is chess. I started playing when I was seven. My grandfather taught me. Now I play three times a week at a club after school. On Saturdays we have small tournaments. Last month I won my first cup. I want to become a champion one day.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How old is Marat?","e":"Twelve","a":"Twelve"},{"q":"Who taught him chess?","e":"His grandfather","a":"His grandfather"},{"q":"How often does he play at the club?","e":"Three times a week","a":"Three times a week"},{"q":"What did he win last month?","e":"His first cup","a":"His first cup"},{"q":"What does he want to become?","e":"A champion","a":"A champion"}]},{"level":"A2","task":["Write a weather forecast for your city."],"title":"Weather forecast","script":"Narrator: Good evening. Here is the weather for tomorrow. In the north it will be cold and snowy, with temperatures around minus eight. In the capital it will be cloudy with a little wind, minus two degrees. In the south it will be sunny and warmer, about plus five. On Wednesday the snow will stop everywhere. Don\u0027t forget your warm coat and hat!","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What is the weather in the north?","e":"Cold and snowy","a":"Cold and snowy"},{"q":"What is the temperature in the capital?","e":"Minus two","a":"Minus two"},{"q":"Where will it be sunny?","e":"In the south","a":"In the south"},{"q":"When will the snow stop?","e":"On Wednesday","a":"On Wednesday"},{"q":"What should people wear?","e":"A warm coat and hat","a":"A warm coat and hat"}]},{"level":"A2","task":["Role-play check-in with your own details."],"title":"At the airport check-in","script":"Agent: Good afternoon. Passport, please.\nPassenger: Here you are.\nAgent: Do you have any luggage to check in?\nPassenger: Yes, one suitcase.\nAgent: It weighs eighteen kilos, that\u0027s fine. Your gate is number 7. Boarding starts at 4:30.\nPassenger: Thank you. Where is the cafe?\nAgent: Upstairs, on the left.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Passenger":"m","Agent":"f"},"tasks":[{"q":"What does the agent ask for first?","e":"A passport","a":"A passport"},{"q":"How many suitcases does the passenger check in?","e":"One","a":"One"},{"q":"How heavy is the suitcase?","e":"Eighteen kilos","a":"Eighteen kilos"},{"q":"Which gate?","e":"Gate 7","a":"Gate 7"},{"q":"Where is the cafe?","e":"Upstairs on the left","a":"Upstairs on the left"}]},{"level":"A2","task":["Write your own timetable for one day."],"title":"School timetable","script":"Teacher: Class, here is your timetable for this week. On Monday you have maths at nine and English at ten. On Tuesday you have geography and PE. Wednesday is a short day: only three lessons. On Thursday there is a test in biology. On Friday you have art and music, and then you go home at one o\u0027clock.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Teacher":"f"},"tasks":[{"q":"What do they have on Monday at ten?","e":"English","a":"English"},{"q":"How many lessons are there on Wednesday?","e":"Three","a":"Three"},{"q":"What is on Thursday?","e":"A biology test","a":"A biology test"},{"q":"What lessons are on Friday?","e":"Art and music","a":"Art and music"},{"q":"What time do they go home on Friday?","e":"One o\u0027clock","a":"One o\u0027clock"}]},{"level":"A2","task":["Describe your best friend in eight sentences."],"title":"Describing a person","script":"Narrator: My best friend is called Dana. She is thirteen years old. She is tall and slim, with long black hair and brown eyes. She is very kind and funny. She always helps me with my homework. She likes dancing and drawing. At weekends we go to the park together and take photos.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How old is Dana?","e":"Thirteen","a":"Thirteen"},{"q":"What does she look like?","e":"Tall and slim, with long black hair and brown eyes","a":"Tall and slim, with long black hair and brown eyes"},{"q":"What is her character like?","e":"Kind and funny","a":"Kind and funny"},{"q":"What does she like?","e":"Dancing and drawing","a":"Dancing and drawing"},{"q":"What do they do at weekends?","e":"Go to the park and take photos","a":"Go to the park and take photos"}]},{"level":"A2","task":["Write a similar phone dialogue with a different order."],"title":"Ordering a pizza by phone","script":"Worker: Pizza House, good evening.\nCustomer: Hello. I\u0027d like to order a large pizza with cheese and mushrooms.\nWorker: Anything to drink?\nCustomer: Two bottles of orange juice, please.\nWorker: That\u0027s 4,800 tenge. What is your address?\nCustomer: Abay Street, number 15, flat 9.\nWorker: It will be with you in thirty minutes.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Customer":"m","Worker":"f"},"tasks":[{"q":"What size is the pizza?","e":"Large","a":"Large"},{"q":"What is on the pizza?","e":"Cheese and mushrooms","a":"Cheese and mushrooms"},{"q":"What does the customer drink?","e":"Orange juice","a":"Orange juice"},{"q":"What is the total price?","e":"4,800 tenge","a":"4,800 tenge"},{"q":"How long will it take?","e":"Thirty minutes","a":"Thirty minutes"}]},{"level":"A2","task":["Write about a place you visited (60 words)."],"title":"A day at the zoo","script":"Narrator: Last Sunday our class went to the zoo. We saw elephants, lions, monkeys and many birds. The elephants were very big and they ate a lot of grass. The monkeys jumped and played. At twelve o\u0027clock we had lunch near the lake. In the afternoon a guide told us about penguins. It was a great day and we took a lot of photos.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"When did the class go to the zoo?","e":"Last Sunday","a":"Last Sunday"},{"q":"Which animals did they see first?","e":"Elephants, lions, monkeys and birds","a":"Elephants, lions, monkeys and birds"},{"q":"What did the elephants eat?","e":"Grass","a":"Grass"},{"q":"Where did they have lunch?","e":"Near the lake","a":"Near the lake"},{"q":"What did the guide talk about?","e":"Penguins","a":"Penguins"}]},{"level":"A2","task":["Plan a birthday party: write the programme with times."],"title":"A birthday party","script":"Aida: Hi, Dana! Thank you for coming to my birthday party.\nDana: Happy birthday, Aida! This present is for you.\nAida: Oh, a book! I love it. Please come and sit. We have cake and juice.\nDana: What time do we play games?\nAida: At five. After that we watch a film. Mum will take everyone home at eight.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Dana":"m","Aida":"f"},"tasks":[{"q":"Whose birthday is it?","e":"Aida\u0027s","a":"Aida\u0027s"},{"q":"What present does Dana give?","e":"A book","a":"A book"},{"q":"What food do they have?","e":"Cake and juice","a":"Cake and juice"},{"q":"At what time do they play games?","e":"At five","a":"At five"},{"q":"When does the party end?","e":"At eight","a":"At eight"}]},{"level":"B1","task":["Prepare answers to \"Tell me about yourself\" and \"Where do you see yourself in five years?\""],"title":"Job interview","script":"Interviewer: Thank you for coming, Ms Nurlan. Why do you want to work for our company?\nCandidate: I\u0027ve followed your projects for years, and I\u0027d like to develop my skills in marketing with a creative team.\nInterviewer: What experience do you have?\nCandidate: I worked for two years at a small agency, where I managed social media campaigns and increased followers by forty percent.\nInterviewer: What is your greatest weakness?\nCandidate: Sometimes I spend too long on details, but I\u0027m learning to set deadlines for myself.\nInterviewer: Thank you. We\u0027ll contact you by Friday.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Interviewer":"f","Candidate":"m"},"tasks":[{"q":"Which area does the candidate want to work in?","e":"Marketing","a":"Marketing"},{"q":"How long did she work at the agency?","e":"Two years","a":"Two years"},{"q":"By how much did she increase followers?","e":"Forty percent","a":"Forty percent"},{"q":"What is her weakness?","e":"She spends too long on details","a":"She spends too long on details"},{"q":"When will the company contact her?","e":"By Friday","a":"By Friday"}]},{"level":"B1","task":["Write a short news bulletin (5 sentences) about your school."],"title":"Radio news bulletin","script":"Narrator: Good evening. Here are the main news. Heavy snow has closed several roads in the north of the country, and drivers are advised to stay at home. In sport, the national team won 3-1 against Uzbekistan in last night\u0027s match. A new science museum will open in the capital next month, with free entry for children. Finally, tomorrow\u0027s weather: cold and windy, with temperatures between minus ten and minus fifteen degrees.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Why have roads been closed?","e":"Heavy snow","a":"Heavy snow"},{"q":"What was the score of the match?","e":"3-1","a":"3-1"},{"q":"Who benefits from free entry to the museum?","e":"Children","a":"Children"},{"q":"When will the museum open?","e":"Next month","a":"Next month"},{"q":"What will the weather be like tomorrow?","e":"Cold and windy, -10 to -15 degrees","a":"Cold and windy, -10 to -15 degrees"}]},{"level":"B1","task":["Write an announcement about a train delay."],"title":"Airport announcement","script":"Narrator: Attention please. Flight KC 721 to Almaty is now ready for boarding at gate 14. Passengers in rows 20 to 30 are requested to board first. Please have your passport and boarding pass ready. Flight KC 305 to Dubai has been delayed by one hour due to technical reasons. The new departure time is 18:40. We apologise for the inconvenience.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Where is flight KC 721 going?","e":"Almaty","a":"Almaty"},{"q":"At which gate is boarding?","e":"Gate 14","a":"Gate 14"},{"q":"Which rows board first?","e":"20 to 30","a":"20 to 30"},{"q":"Why is the Dubai flight delayed?","e":"Technical reasons","a":"Technical reasons"},{"q":"What is the new departure time of the Dubai flight?","e":"18:40","a":"18:40"}]},{"level":"B1","task":["Do you agree with Aida or Marat? Give two reasons."],"title":"Discussion about technology","script":"Aida: I think smartphones make our lives easier. We can find information in seconds.\nMarat: I agree, but I also believe they distract us. People often look at screens instead of talking to each other.\nAida: That\u0027s true. However, it depends on how we use them. For example, I learn languages with apps.\nMarat: Good point. Maybe the solution is to limit screen time, say two hours a day.","spec":"Listening · 4 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Marat":"m","Aida":"f"},"tasks":[{"q":"What does Aida say about smartphones?","e":"They make life easier","a":"They make life easier"},{"q":"What problem does Marat see?","e":"They distract people","a":"They distract people"},{"q":"How does Aida use her phone for learning?","e":"She learns languages with apps","a":"She learns languages with apps"},{"q":"What solution does Marat suggest?","e":"Limit screen time to two hours a day","a":"Limit screen time to two hours a day"}]},{"level":"B1","task":["What can your school do to reduce waste? Suggest three ideas."],"title":"Lecture on recycling","script":"Narrator: Good morning, everyone. Today I\u0027d like to talk about recycling. Every person produces about half a kilogram of waste a day. Around one third of this waste could be recycled, but in many countries less than ten percent actually is. Glass, paper and metal can be reused many times. Plastic is more difficult, because many types cannot be recycled together. We can help by separating waste at home and by buying products with less packaging.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How much waste does a person produce daily?","e":"About half a kilogram","a":"About half a kilogram"},{"q":"What fraction of waste could be recycled?","e":"About one third","a":"About one third"},{"q":"What percentage is actually recycled in many countries?","e":"Less than ten percent","a":"Less than ten percent"},{"q":"Which materials can be reused many times?","e":"Glass, paper and metal","a":"Glass, paper and metal"},{"q":"How can we help?","e":"Separate waste, buy less packaging","a":"Separate waste, buy less packaging"}]},{"level":"B1","task":["Role-play a complaint about a different product."],"title":"Complaining in a shop","script":"Customer: Excuse me, I bought these headphones here yesterday, but one of them doesn\u0027t work.\nAssistant: I\u0027m sorry to hear that. Do you have the receipt?\nCustomer: Yes, here it is.\nAssistant: Thank you. I can offer you a replacement or a full refund.\nCustomer: I\u0027d prefer a refund, please.\nAssistant: Of course. It will take a few minutes.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Customer":"f","Assistant":"m"},"tasks":[{"q":"What did the customer buy?","e":"Headphones","a":"Headphones"},{"q":"What is the problem?","e":"One of them doesn\u0027t work","a":"One of them doesn\u0027t work"},{"q":"What does the assistant ask for?","e":"The receipt","a":"The receipt"},{"q":"What two options does the assistant offer?","e":"A replacement or a refund","a":"A replacement or a refund"},{"q":"Which option does the customer choose?","e":"A refund","a":"A refund"}]},{"level":"B1","task":["Write a sleep plan for a week."],"title":"A podcast about sleep","script":"Narrator: Welcome to the Health Hour. Today we discuss sleep. Experts say teenagers need between eight and ten hours a night, but many sleep only six. The main reasons are late-night phone use and irregular schedules. Poor sleep reduces concentration, and it can lead to weight gain. To improve your sleep, go to bed at the same time every day, avoid screens an hour before bed, and keep your room cool and dark.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How many hours do teenagers need?","e":"Eight to ten","a":"Eight to ten"},{"q":"How many hours do many teenagers sleep?","e":"Six","a":"Six"},{"q":"What are the main reasons for poor sleep?","e":"Late-night phone use and irregular schedules","a":"Late-night phone use and irregular schedules"},{"q":"Name one effect of poor sleep.","e":"Reduced concentration or weight gain","a":"Reduced concentration or weight gain"},{"q":"Name two ways to improve sleep.","e":"Same bedtime, no screens before bed, cool and dark room","a":"Same bedtime, no screens before bed, cool and dark room"}]},{"level":"B1","task":["Prepare a one-minute tour of a place in your city."],"title":"Tour guide at a museum","script":"Narrator: Welcome to the National Museum. Please follow me. This hall contains objects from the Bronze Age, including the famous golden warrior costume. It was discovered in 1969 in a burial mound near Almaty. The museum is open from ten to six, and photographs without a flash are allowed. After the tour, you can visit the gift shop on the ground floor.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What does the hall contain?","e":"Objects from the Bronze Age","a":"Objects from the Bronze Age"},{"q":"What is the famous exhibit?","e":"The golden warrior costume","a":"The golden warrior costume"},{"q":"When was it found?","e":"In 1969","a":"In 1969"},{"q":"What are the opening hours?","e":"Ten to six","a":"Ten to six"},{"q":"Where is the gift shop?","e":"On the ground floor","a":"On the ground floor"}]},{"level":"B1","task":["Write an advertisement for a flat you would like to rent."],"title":"Renting a flat","script":"Agent: The flat has two bedrooms, a kitchen and a balcony. It is on the fourth floor, near a metro station.\nClient: How much is the rent?\nAgent: 200,000 tenge a month, plus utilities.\nClient: Is it furnished?\nAgent: Yes, the kitchen and the bedrooms are fully furnished. Pets are not allowed.\nClient: I\u0027d like to see it tomorrow evening.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Client":"m","Agent":"f"},"tasks":[{"q":"How many bedrooms does the flat have?","e":"Two","a":"Two"},{"q":"Which floor is it on?","e":"The fourth","a":"The fourth"},{"q":"How much is the rent?","e":"200,000 tenge a month plus utilities","a":"200,000 tenge a month plus utilities"},{"q":"Is it furnished?","e":"Yes","a":"Yes"},{"q":"Are pets allowed?","e":"No","a":"No"}]},{"level":"B1","task":["Give five pieces of advice to a new student."],"title":"Giving advice about studying","script":"Narrator: Many students leave their revision until the last minute. A better approach is to study a little every day. Start with the hardest subject, when you are fresh. Take a ten-minute break every hour. Make notes and test yourself. Finally, sleep well before the exam, because tired students make more mistakes.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What do many students do?","e":"Leave revision until the last minute","a":"Leave revision until the last minute"},{"q":"What is a better approach?","e":"Study a little every day","a":"Study a little every day"},{"q":"Which subject should you start with?","e":"The hardest","a":"The hardest"},{"q":"How often should you take a break?","e":"Every hour for ten minutes","a":"Every hour for ten minutes"},{"q":"Why is sleep important?","e":"Tired students make more mistakes","a":"Tired students make more mistakes"}]},{"level":"B1","task":["Would you use this service? Give two reasons."],"title":"A car-sharing service","script":"Narrator: A new car-sharing service has started in the capital. Users download an app, find a nearby car and unlock it with their phone. The price is 40 tenge per minute, including fuel and insurance. The company says the service will reduce traffic and parking problems. However, some residents worry that cars are often left in the wrong places.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How do users unlock the car?","e":"With their phone","a":"With their phone"},{"q":"How much does it cost?","e":"40 tenge per minute","a":"40 tenge per minute"},{"q":"What does the price include?","e":"Fuel and insurance","a":"Fuel and insurance"},{"q":"What benefit does the company mention?","e":"Less traffic and parking problems","a":"Less traffic and parking problems"},{"q":"What do some residents worry about?","e":"Cars left in the wrong places","a":"Cars left in the wrong places"}]},{"level":"B1","task":["Role-play a complaint in a hotel."],"title":"Describing a holiday problem","script":"Guest: Excuse me, there is a problem with my room. The air conditioner doesn\u0027t work and it is very hot.\nReceptionist: I\u0027m very sorry. Which room are you in?\nGuest: Room 214. Also, there is no hot water.\nReceptionist: I\u0027ll send a technician immediately. If it can\u0027t be fixed in an hour, we\u0027ll move you to another room.\nGuest: Thank you. I\u0027d appreciate that.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Receptionist":"m","Guest":"f"},"tasks":[{"q":"What is the first problem?","e":"The air conditioner doesn\u0027t work","a":"The air conditioner doesn\u0027t work"},{"q":"What is the room number?","e":"214","a":"214"},{"q":"What is the second problem?","e":"No hot water","a":"No hot water"},{"q":"What will the receptionist send?","e":"A technician","a":"A technician"},{"q":"What happens if it can\u0027t be fixed in an hour?","e":"The guest will be moved to another room","a":"The guest will be moved to another room"}]},{"level":"B1","task":["Write an announcement for a school event."],"title":"A school trip announcement","script":"Narrator: Attention, students of grade ten. On Friday we will visit the science park in the city centre. The bus leaves from the school gate at eight thirty sharp. Please bring a packed lunch and a bottle of water. Wear comfortable shoes. Parents must sign the permission form by Wednesday. We expect to be back at three.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Where is the trip?","e":"The science park","a":"The science park"},{"q":"What time does the bus leave?","e":"8:30","a":"8:30"},{"q":"What should students bring?","e":"A packed lunch and water","a":"A packed lunch and water"},{"q":"When must parents sign the form?","e":"By Wednesday","a":"By Wednesday"},{"q":"When will they be back?","e":"At three","a":"At three"}]},{"level":"B1","task":["Recommend a book to a friend in six sentences."],"title":"Talking about a book","script":"Anna: Have you finished the book I lent you?\nBek: Yes, last night. I couldn\u0027t stop reading.\nAnna: What did you like most?\nBek: The characters. The main hero is very brave, but he is also afraid sometimes, so he feels real.\nAnna: And the ending?\nBek: It was surprising. I didn\u0027t expect it at all.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Bek":"m","Anna":"f"},"tasks":[{"q":"When did Bek finish the book?","e":"Last night","a":"Last night"},{"q":"What did Bek like most?","e":"The characters","a":"The characters"},{"q":"Describe the hero.","e":"Brave but sometimes afraid","a":"Brave but sometimes afraid"},{"q":"What does Bek say about the ending?","e":"It was surprising","a":"It was surprising"},{"q":"Did he expect it?","e":"No","a":"No"}]},{"level":"B2","task":["Suggest three improvements to the scheme."],"title":"A city bike scheme","script":"Narrator: City officials have launched a bike-sharing scheme with five hundred bicycles at fifty stations. A single ride costs 200 tenge for thirty minutes. In the first month, more than twenty thousand people used the bikes. The mayor said the aim is to cut pollution and encourage healthy habits. Cyclists asked for more bike lanes, because some roads are still dangerous.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How many bicycles are there?","e":"Five hundred","a":"Five hundred"},{"q":"How much is one ride?","e":"200 tenge for thirty minutes","a":"200 tenge for thirty minutes"},{"q":"How many people used it in the first month?","e":"More than twenty thousand","a":"More than twenty thousand"},{"q":"What is the aim of the scheme?","e":"Cut pollution and encourage healthy habits","a":"Cut pollution and encourage healthy habits"},{"q":"What do cyclists ask for?","e":"More bike lanes","a":"More bike lanes"}]},{"level":"B2","task":["Role-play asking a neighbour for a favour."],"title":"Asking for a favour","script":"Dana: Aida, could you do me a favour?\nAida: Of course. What is it?\nDana: I\u0027m going away this weekend. Could you water my plants and feed the cat?\nAida: No problem. Where do you keep the cat food?\nDana: It\u0027s in the cupboard under the sink. Thanks so much. I\u0027ll bring you a present.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Aida":"m","Dana":"f"},"tasks":[{"q":"What does Dana ask Aida to do?","e":"Water the plants and feed the cat","a":"Water the plants and feed the cat"},{"q":"When is Dana away?","e":"This weekend","a":"This weekend"},{"q":"Where is the cat food?","e":"In the cupboard under the sink","a":"In the cupboard under the sink"},{"q":"What does Dana promise?","e":"To bring a present","a":"To bring a present"},{"q":"How does Aida answer?","e":"No problem","a":"No problem"}]},{"level":"B2","task":["Write a 40-word radio advert for a product."],"title":"A radio advert","script":"Narrator: Are you tired of slow internet? Switch to FastNet! For only 5,000 tenge a month you get unlimited data and speeds up to one hundred megabits. Installation is free this month. Call 8-800-123-45-67 or visit our website. FastNet: always connected.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What problem does the advert mention?","e":"Slow internet","a":"Slow internet"},{"q":"What is the monthly price?","e":"5,000 tenge","a":"5,000 tenge"},{"q":"What is the maximum speed?","e":"One hundred megabits","a":"One hundred megabits"},{"q":"What is free this month?","e":"Installation","a":"Installation"},{"q":"How can you contact the company?","e":"Call or visit the website","a":"Call or visit the website"}]},{"level":"B2","task":["Write safety advice for a storm."],"title":"A weather report on a storm","script":"Narrator: Authorities have issued a storm warning for the western region. Winds of up to one hundred kilometres an hour are expected from Thursday night. Residents are advised to stay indoors, secure loose objects and avoid travelling. Schools will be closed on Friday. The storm should weaken by Saturday morning.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Which region has the warning?","e":"The western region","a":"The western region"},{"q":"How strong will the wind be?","e":"Up to 100 km/h","a":["Up to 100 km","h"]},{"q":"When does it start?","e":"Thursday night","a":"Thursday night"},{"q":"What will happen on Friday?","e":"Schools will be closed","a":"Schools will be closed"},{"q":"When will the storm weaken?","e":"Saturday morning","a":"Saturday morning"}]},{"level":"B2","task":["Write a dialogue for an appointment at a hairdresser\u0027s."],"title":"Making an appointment","script":"Receptionist: Dental clinic, good morning.\nPatient: Hello, I\u0027d like to make an appointment. I have toothache.\nReceptionist: Can you come at 11 tomorrow?\nPatient: I have lessons then. Is the afternoon possible?\nReceptionist: We have a free slot at 4:30.\nPatient: Perfect. My name is Mira Bekova.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Patient":"m","Receptionist":"f"},"tasks":[{"q":"Why does the patient call?","e":"To make an appointment because of toothache","a":"To make an appointment because of toothache"},{"q":"What time does the receptionist suggest first?","e":"11 tomorrow","a":"11 tomorrow"},{"q":"Why can\u0027t the patient come then?","e":"Lessons","a":"Lessons"},{"q":"What time is the final appointment?","e":"4:30","a":"4:30"},{"q":"What is the patient\u0027s name?","e":"Mira Bekova","a":"Mira Bekova"}]},{"level":"B2","task":["Invent a project for a science competition."],"title":"News about a school competition","script":"Narrator: School number 12 has won the regional science competition. Students built a small wind turbine that can charge a phone. The team of four worked on the project for six months. Their teacher said the students learned teamwork and problem solving. The winners will represent the region at the national finals in May.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Which school won?","e":"School number 12","a":"School number 12"},{"q":"What did the students build?","e":"A small wind turbine","a":"A small wind turbine"},{"q":"How long did they work?","e":"Six months","a":"Six months"},{"q":"What did they learn, according to the teacher?","e":"Teamwork and problem solving","a":"Teamwork and problem solving"},{"q":"When are the national finals?","e":"In May","a":"In May"}]},{"level":"B2","task":["Write a short CV for this job."],"title":"A job advertisement","script":"Narrator: We are looking for a friendly cafe assistant. You will serve customers, prepare drinks and keep the cafe clean. No experience is required, but you must be reliable and polite. The job is part-time, three afternoons a week, and the pay is 1,500 tenge an hour. To apply, send your CV to the manager by the end of the month.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What is the job?","e":"Cafe assistant","a":"Cafe assistant"},{"q":"What will you do?","e":"Serve customers, prepare drinks, keep the cafe clean","a":"Serve customers, prepare drinks, keep the cafe clean"},{"q":"Is experience required?","e":"No","a":"No"},{"q":"What is the pay?","e":"1,500 tenge an hour","a":"1,500 tenge an hour"},{"q":"When is the deadline?","e":"The end of the month","a":"The end of the month"}]},{"level":"B2","task":["Write about your childhood using used to."],"title":"Talking about the past","script":"Narrator: When I was a child, we lived in a small village near the mountains. Every summer I helped my grandfather with the horses. We woke up at five, and after breakfast we drove the horses to the river. In the evenings, my grandmother told us old stories. I didn\u0027t have a phone or a computer, but I was very happy.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Where did the speaker live?","e":"In a village near the mountains","a":"In a village near the mountains"},{"q":"What did he/she do every summer?","e":"Helped the grandfather with horses","a":"Helped the grandfather with horses"},{"q":"What time did they wake up?","e":"At five","a":"At five"},{"q":"What did the grandmother do?","e":"Told old stories","a":"Told old stories"},{"q":"Did the speaker have a phone?","e":"No","a":"No"}]},{"level":"B2","task":["Role-play reporting a lost item."],"title":"A lost wallet","script":"Passenger: Excuse me, I think I left my wallet on the bus.\nOfficer: When was this?\nPassenger: About an hour ago, on bus number 25.\nOfficer: Can you describe it?\nPassenger: It\u0027s black leather with a blue card inside and about ten thousand tenge.\nOfficer: Please fill in this form. We\u0027ll call you if we find it.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Passenger":"f","Officer":"m"},"tasks":[{"q":"What did the passenger lose?","e":"A wallet","a":"A wallet"},{"q":"Which bus?","e":"Number 25","a":"Number 25"},{"q":"What colour is it?","e":"Black","a":"Black"},{"q":"What is inside?","e":"A blue card and about 10,000 tenge","a":"A blue card and about 10,000 tenge"},{"q":"What must the passenger do?","e":"Fill in a form","a":"Fill in a form"}]},{"level":"B2","task":["What is your opinion? Write six sentences."],"title":"Talking about technology at school","script":"Teacher: Today we will discuss using tablets in lessons.\nStudent A: I think tablets are great because we can find information quickly.\nStudent B: I agree, but I also believe that paper books help us concentrate better.\nTeacher: Good point. Perhaps we need both. Next week we\u0027ll test the idea in a geography lesson.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Student B":"f","Teacher":"f","Student A":"m"},"tasks":[{"q":"What is the topic?","e":"Using tablets in lessons","a":"Using tablets in lessons"},{"q":"What advantage does Student A mention?","e":"Finding information quickly","a":"Finding information quickly"},{"q":"What does Student B believe?","e":"Paper books help concentration","a":"Paper books help concentration"},{"q":"What does the teacher suggest?","e":"We need both","a":"We need both"},{"q":"When will they test the idea?","e":"Next week in geography","a":"Next week in geography"}]},{"level":"B2","task":["Write five questions about volcanoes for a quiz."],"title":"A short lecture on volcanoes","script":"Narrator: Volcanoes form where hot rock from inside the Earth reaches the surface. There are about fifteen hundred active volcanoes in the world, and most are located around the Pacific Ocean in an area known as the Ring of Fire. When a volcano erupts, it can send ash high into the sky and cause flights to be cancelled. However, volcanic soil is very fertile, which is why many people live near volcanoes.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What is a volcano?","e":"A place where hot rock reaches the surface","a":"A place where hot rock reaches the surface"},{"q":"How many active volcanoes are there?","e":"About fifteen hundred","a":"About fifteen hundred"},{"q":"What is the Ring of Fire?","e":"An area around the Pacific Ocean with most volcanoes","a":"An area around the Pacific Ocean with most volcanoes"},{"q":"What can ash cause?","e":"Cancelled flights","a":"Cancelled flights"},{"q":"Why do people live near volcanoes?","e":"The soil is fertile","a":"The soil is fertile"}]},{"level":"B2","task":["Write instructions for your favourite simple dish."],"title":"Cooking instructions","script":"Narrator: To make a simple vegetable soup, first chop two carrots, one onion and three potatoes. Heat a spoonful of oil in a large pan and fry the onion for three minutes. Add the carrots and potatoes and pour in one litre of water. Cook for twenty minutes, then add salt and pepper. Serve hot with fresh bread.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What vegetables are needed?","e":"Carrots, onion and potatoes","a":"Carrots, onion and potatoes"},{"q":"How long do you fry the onion?","e":"Three minutes","a":"Three minutes"},{"q":"How much water do you add?","e":"One litre","a":"One litre"},{"q":"How long do you cook the soup?","e":"Twenty minutes","a":"Twenty minutes"},{"q":"What do you serve it with?","e":"Fresh bread","a":"Fresh bread"}]},{"level":"B2","task":["Write a short traffic report for your town."],"title":"A traffic report","script":"Narrator: Good morning drivers. There is heavy traffic on Republic Avenue because of an accident near the bridge. Expect delays of up to forty minutes. We recommend using Abay Street instead. The north ring road is clear. Buses on route 12 are running ten minutes late. The accident should be cleared by nine thirty.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Why is the traffic heavy?","e":"An accident near the bridge","a":"An accident near the bridge"},{"q":"How long are the delays?","e":"Up to forty minutes","a":"Up to forty minutes"},{"q":"Which road is recommended?","e":"Abay Street","a":"Abay Street"},{"q":"Which road is clear?","e":"The north ring road","a":"The north ring road"},{"q":"When will the accident be cleared?","e":"By nine thirty","a":"By nine thirty"}]},{"level":"B2","task":["Write a poster for a lost pet."],"title":"A phone call about a lost cat","script":"Caller: Hello, I\u0027ve found a grey cat with white paws near the park.\nOwner: Oh, that must be Murka! She disappeared two days ago.\nCaller: She looks healthy. She\u0027s wearing a blue collar.\nOwner: Yes, that\u0027s her. Where can I pick her up?\nCaller: I live at 25 Pushkin Street, flat 4. Come after six.\nOwner: I\u0027ll be there. Thank you so much!","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Caller":"f","Owner":"m"},"tasks":[{"q":"What did the caller find?","e":"A grey cat with white paws","a":"A grey cat with white paws"},{"q":"What is the cat\u0027s name?","e":"Murka","a":"Murka"},{"q":"What colour is the collar?","e":"Blue","a":"Blue"},{"q":"Where does the caller live?","e":"25 Pushkin Street, flat 4","a":"25 Pushkin Street, flat 4"},{"q":"When can the owner come?","e":"After six","a":"After six"}]},{"level":"C1","task":["Summarise the lecture in 60 words."],"title":"Academic lecture on climate change","script":"Narrator: Today we will examine the evidence for anthropogenic climate change. Since the Industrial Revolution, atmospheric carbon dioxide has risen by roughly fifty percent. This increase correlates strongly with the global average temperature, which has climbed by about one point one degrees Celsius. Sceptics sometimes point to natural cycles, but those operate over thousands of years rather than decades. Mitigation requires a rapid transition away from fossil fuels, while adaptation addresses the effects that are already unavoidable.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"By how much has atmospheric CO2 risen since the Industrial Revolution?","e":"About fifty percent","a":"About fifty percent"},{"q":"How much has the global temperature risen?","e":"About 1.1 degrees Celsius","a":"About 1.1 degrees Celsius"},{"q":"What argument do sceptics use?","e":"Natural cycles","a":"Natural cycles"},{"q":"Why is their argument weak?","e":"Natural cycles take thousands of years, not decades","a":"Natural cycles take thousands of years, not decades"},{"q":"What is the difference between mitigation and adaptation?","e":"Mitigation reduces the causes; adaptation deals with unavoidable effects","a":"Mitigation reduces the causes; adaptation deals with unavoidable effects"}]},{"level":"C1","task":["Write a 150-word statement for or against the motion."],"title":"Debate on remote work","script":"Host: Today\u0027s motion: remote work should become the norm.\nSpeaker A: Remote work increases productivity and saves commuting time. Companies also reduce office costs, which allows higher salaries.\nSpeaker B: I would argue that creativity suffers without face-to-face interaction. Moreover, younger employees lose valuable mentoring opportunities.\nSpeaker A: A hybrid model could resolve both concerns.\nSpeaker B: Perhaps, though it remains difficult to coordinate in practice.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Host":"f","Speaker B":"f","Speaker A":"m"},"tasks":[{"q":"What is the motion?","e":"Remote work should become the norm","a":"Remote work should become the norm"},{"q":"Name two arguments for remote work.","e":"Higher productivity, savings on commuting/office costs","a":["Higher productivity, savings on commuting","office costs"]},{"q":"What does Speaker B say about creativity?","e":"It suffers without face-to-face interaction","a":"It suffers without face-to-face interaction"},{"q":"What do younger employees lose, according to B?","e":"Mentoring opportunities","a":"Mentoring opportunities"},{"q":"What compromise does Speaker A suggest?","e":"A hybrid model","a":"A hybrid model"}]},{"level":"C1","task":["Write three follow-up questions you would ask Dr Kassym."],"title":"Interview with a scientist","script":"Interviewer: Dr Kassym, your team recently discovered a new protein linked to memory. How significant is it?\nDr Kassym: It\u0027s an important step, but we must be cautious. The protein appears to strengthen synaptic connections in mice. Whether the same applies to humans remains to be seen.\nInterviewer: When might this lead to treatment?\nDr Kassym: Realistically, at least a decade. Clinical trials are lengthy, and many promising compounds fail.\nInterviewer: What would you say to people expecting a miracle cure?\nDr Kassym: Science progresses incrementally. Hype is the enemy of good research.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Interviewer":"f","Dr Kassym":"m"},"tasks":[{"q":"What did the team discover?","e":"A protein linked to memory","a":"A protein linked to memory"},{"q":"In which organism was the effect observed?","e":"Mice","a":"Mice"},{"q":"How long until a possible treatment?","e":"At least a decade","a":"At least a decade"},{"q":"Why is it so slow?","e":"Clinical trials are lengthy and many compounds fail","a":"Clinical trials are lengthy and many compounds fail"},{"q":"What is the scientist\u0027s attitude to hype?","e":"It is the enemy of good research","a":"It is the enemy of good research"}]},{"level":"C1","task":["Write three phrases used to make concessions in negotiations."],"title":"Business negotiation","script":"Buyer: We are interested in a long-term contract, but your price is above our budget.\nSeller: We could offer a five percent discount for orders above ten thousand units.\nBuyer: That is a step in the right direction. Could you also extend the payment period to sixty days?\nSeller: We would have to review the terms, but thirty days is feasible.\nBuyer: Let\u0027s settle on forty-five days and a six percent discount.\nSeller: I\u0027d need approval, but I think we can reach an agreement.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Buyer":"f","Seller":"m"},"tasks":[{"q":"What is the buyer\u0027s problem with the offer?","e":"The price is above the budget","a":"The price is above the budget"},{"q":"What discount does the seller first offer?","e":"Five percent for orders above 10,000 units","a":"Five percent for orders above 10,000 units"},{"q":"What payment period does the buyer ask for?","e":"Sixty days","a":"Sixty days"},{"q":"What compromise does the buyer propose?","e":"45 days and 6 percent discount","a":"45 days and 6 percent discount"},{"q":"What does the seller need before agreeing?","e":"Approval","a":"Approval"}]},{"level":"C1","task":["Write a paragraph about how trade shapes culture."],"title":"Documentary on the Silk Road","script":"Narrator: For over fifteen hundred years, the network of routes known as the Silk Road connected China with the Mediterranean. Merchants rarely travelled the whole distance; goods passed through many hands. Silk and spices moved west, while horses, glass and silver moved east. Equally important was the exchange of ideas: Buddhism, paper-making and mathematics spread along these routes. Cities such as Samarkand and Turkistan flourished as centres of trade and scholarship.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How long did the Silk Road operate?","e":"Over fifteen hundred years","a":"Over fifteen hundred years"},{"q":"Did merchants travel the entire route?","e":"Rarely, goods passed through many hands","a":"Rarely, goods passed through many hands"},{"q":"Name two goods that moved west.","e":"Silk and spices","a":"Silk and spices"},{"q":"What ideas spread along the routes?","e":"Buddhism, paper-making, mathematics","a":"Buddhism, paper-making, mathematics"},{"q":"Which cities are mentioned?","e":"Samarkand and Turkistan","a":"Samarkand and Turkistan"}]},{"level":"C1","task":["Which view do you agree with? Write 120 words."],"title":"Panel discussion on artificial intelligence","script":"Moderator: Will artificial intelligence replace human teachers?\nPanelist 1: Not entirely. AI can personalise lessons, but empathy and mentoring remain human strengths.\nPanelist 2: I\u0027d go further: AI will transform teaching rather than replace it. Teachers will focus on critical thinking and social skills.\nPanelist 3: The danger is inequality. Not every school can afford advanced technology.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Moderator":"f"},"tasks":[{"q":"What can AI do well, according to Panelist 1?","e":"Personalise lessons","a":"Personalise lessons"},{"q":"What remains human strengths?","e":"Empathy and mentoring","a":"Empathy and mentoring"},{"q":"How will teaching change, according to Panelist 2?","e":"Teachers will focus on critical thinking and social skills","a":"Teachers will focus on critical thinking and social skills"},{"q":"What danger does Panelist 3 mention?","e":"Inequality between schools","a":"Inequality between schools"},{"q":"Which panelist is most optimistic?","e":"Panelist 2","a":"Panelist 2"}]},{"level":"C1","task":["Summarise the lecture in 70 words."],"title":"Lecture on urbanisation","script":"Narrator: Over half of the world\u0027s population now lives in cities, and this proportion is expected to reach two thirds by 2050. Urbanisation brings economic opportunities and better access to services, yet it also creates challenges: housing shortages, congestion and pollution. Planners increasingly promote compact cities with efficient public transport and green spaces to make urban life sustainable.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What proportion of people live in cities now?","e":"Over half","a":"Over half"},{"q":"What is predicted for 2050?","e":"Two thirds","a":"Two thirds"},{"q":"Name two benefits of urbanisation.","e":"Economic opportunities and better services","a":"Economic opportunities and better services"},{"q":"Name two challenges.","e":"Housing shortages, congestion, pollution","a":"Housing shortages, congestion, pollution"},{"q":"What do planners promote?","e":"Compact cities with public transport and green spaces","a":"Compact cities with public transport and green spaces"}]},{"level":"C1","task":["Which piece of advice is most useful? Explain in 80 words."],"title":"Radio interview with an entrepreneur","script":"Interviewer: You started your company at twenty-two. What was the biggest obstacle?\nFounder: Funding, without doubt. Banks wouldn\u0027t lend to someone without a track record, so I relied on friends and a small grant.\nInterviewer: Any advice for young founders?\nFounder: Test your idea early, accept that you will fail occasionally, and surround yourself with people who disagree with you constructively.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Interviewer":"f","Founder":"m"},"tasks":[{"q":"How old was the founder when starting the company?","e":"Twenty-two","a":"Twenty-two"},{"q":"What was the biggest obstacle?","e":"Funding","a":"Funding"},{"q":"How did the founder finance the start?","e":"Friends and a small grant","a":"Friends and a small grant"},{"q":"What is the first piece of advice?","e":"Test your idea early","a":"Test your idea early"},{"q":"What kind of people should founders have around them?","e":"People who disagree constructively","a":"People who disagree constructively"}]},{"level":"C1","task":["Discuss two risks and two benefits of AI in medicine."],"title":"A report on artificial intelligence in medicine","script":"Narrator: Hospitals increasingly use algorithms to analyse scans and detect diseases such as cancer at an early stage. In trials, some systems outperformed junior doctors in spotting small tumours. Nevertheless, specialists warn that algorithms are only as good as the data they are trained on, and that decisions affecting patients\u0027 lives must remain under human supervision. Privacy is another pressing concern.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What do hospitals use algorithms for?","e":"To analyse scans and detect diseases early","a":"To analyse scans and detect diseases early"},{"q":"What did trials show?","e":"Some systems outperformed junior doctors","a":"Some systems outperformed junior doctors"},{"q":"What is the main limitation?","e":"The quality of the training data","a":"The quality of the training data"},{"q":"Who must supervise decisions?","e":"Humans","a":"Humans"},{"q":"What other concern is mentioned?","e":"Privacy","a":"Privacy"}]},{"level":"C2","task":["Write a short conclusion to this debate."],"title":"A debate on social media regulation","script":"Speaker A: Platforms profit from engagement, so misinformation spreads quickly. Governments must hold them accountable.\nSpeaker B: Regulation risks censorship. Users should be educated to evaluate sources rather than rely on legal restrictions.\nSpeaker A: Education is slow. Without rules, harm is done before people learn.\nSpeaker B: Then regulation should be narrow, transparent and open to appeal.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Speaker B":"m","Speaker A":"f"},"tasks":[{"q":"Why does misinformation spread, according to A?","e":"Platforms profit from engagement","a":"Platforms profit from engagement"},{"q":"What does A want governments to do?","e":"Hold platforms accountable","a":"Hold platforms accountable"},{"q":"What risk does B see?","e":"Censorship","a":"Censorship"},{"q":"What does B prefer?","e":"Educating users","a":"Educating users"},{"q":"What compromise does B reach?","e":"Narrow, transparent regulation open to appeal","a":"Narrow, transparent regulation open to appeal"}]},{"level":"C2","task":["Design a study plan using spaced repetition."],"title":"A lecture on memory","script":"Narrator: Psychologists distinguish between short-term and long-term memory. Short-term memory holds roughly seven items for around twenty seconds. To transfer information into long-term memory, repetition spaced over time is far more effective than cramming. Emotion also matters: events associated with strong feelings are remembered more vividly, although not necessarily more accurately.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"How many items does short-term memory hold?","e":"About seven","a":"About seven"},{"q":"For how long?","e":"Around twenty seconds","a":"Around twenty seconds"},{"q":"What is more effective than cramming?","e":"Spaced repetition","a":"Spaced repetition"},{"q":"What improves how vividly we remember?","e":"Strong emotion","a":"Strong emotion"},{"q":"Are emotional memories always accurate?","e":"No","a":"No"}]},{"level":"C2","task":["Do you agree with minimalism? Write 120 words."],"title":"A talk on minimalism","script":"Narrator: Minimalism is more than a style of interior design; it is a philosophy. Its advocates argue that owning fewer things frees both time and money, reducing stress. Critics counter that the movement can be a privilege of the affluent, and that giving away possessions is not always practical. Perhaps the most useful lesson is to distinguish what we need from what we merely desire.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What is minimalism, according to the speaker?","e":"A philosophy","a":"A philosophy"},{"q":"What do advocates say owning fewer things gives?","e":"More time and money and less stress","a":"More time and money and less stress"},{"q":"What do critics say?","e":"It is a privilege of the affluent","a":"It is a privilege of the affluent"},{"q":"What is the most useful lesson?","e":"To distinguish need from desire","a":"To distinguish need from desire"},{"q":"Is giving away possessions always practical?","e":"No","a":"No"}]},{"level":"C2","task":["Suggest an ambitious target and explain how to reach it."],"title":"A news report on renewable energy","script":"Narrator: The country has announced plans to generate thirty percent of its electricity from renewable sources by 2030. Several large wind farms are under construction in the south, while solar panels will be installed on public buildings. The government argues that the transition will create jobs and reduce dependence on imports. Environmental groups welcome the plan but say the target is not ambitious enough.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What is the target?","e":"30 percent renewable electricity by 2030","a":"30 percent renewable electricity by 2030"},{"q":"Where are wind farms being built?","e":"In the south","a":"In the south"},{"q":"Where will solar panels be installed?","e":"On public buildings","a":"On public buildings"},{"q":"What benefits does the government mention?","e":"Jobs and less dependence on imports","a":"Jobs and less dependence on imports"},{"q":"What do environmental groups say?","e":"The target is not ambitious enough","a":"The target is not ambitious enough"}]},{"level":"C2","task":["Translate three idioms from your language into English."],"title":"A seminar on translation","script":"Narrator: Translation is never a mechanical substitution of words. A translator must convey tone, cultural references and humour, which often have no direct equivalent. Take idioms: translating them literally usually produces nonsense. Machine translation has improved dramatically, yet it still struggles with ambiguity and context, so human judgement remains indispensable in literary and legal texts.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Why is translation not mechanical?","e":"It must convey tone, culture and humour","a":"It must convey tone, culture and humour"},{"q":"What goes wrong with literal idioms?","e":"It produces nonsense","a":"It produces nonsense"},{"q":"What has improved dramatically?","e":"Machine translation","a":"Machine translation"},{"q":"What does it still struggle with?","e":"Ambiguity and context","a":"Ambiguity and context"},{"q":"Where is human judgement essential?","e":"Literary and legal texts","a":"Literary and legal texts"}]},{"level":"C2","task":["Write three more questions for this interview."],"title":"An interview with a diplomat","script":"Interviewer: What skills does a diplomat need most?\nDiplomat: Listening, patience and cultural sensitivity. Negotiations can last for years, and a single careless remark may undo progress.\nInterviewer: Do you ever disagree with your government\u0027s position?\nDiplomat: Occasionally, but my role is to represent policy, while offering candid advice in private.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Interviewer":"f","Diplomat":"m"},"tasks":[{"q":"Name two skills a diplomat needs.","e":"Listening, patience (or cultural sensitivity)","a":["Listening, patience (or cultural sensitivity)","Listening, patience","Listening, patience or cultural sensitivity"]},{"q":"How long can negotiations last?","e":"Years","a":"Years"},{"q":"What may undo progress?","e":"A careless remark","a":"A careless remark"},{"q":"What is the diplomat\u0027s role?","e":"To represent policy","a":"To represent policy"},{"q":"Where does the diplomat offer candid advice?","e":"In private","a":"In private"}]},{"level":"C2","task":["Propose three changes to improve productivity at school."],"title":"A talk about sleep and productivity","script":"Narrator: Contrary to popular belief, working longer hours does not necessarily increase output. Studies of knowledge workers show that productivity declines sharply after about fifty hours a week. Moreover, chronic sleep deprivation impairs judgement in ways comparable to alcohol intoxication. Companies that encourage rest, flexible hours and short breaks often record higher profits and lower turnover.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"What does the talk contradict?","e":"The belief that longer hours increase output","a":"The belief that longer hours increase output"},{"q":"After how many hours does productivity decline?","e":"About fifty a week","a":"About fifty a week"},{"q":"What is sleep deprivation compared to?","e":"Alcohol intoxication","a":"Alcohol intoxication"},{"q":"Which practices help companies?","e":"Rest, flexible hours and short breaks","a":"Rest, flexible hours and short breaks"},{"q":"What results do such companies record?","e":"Higher profits and lower turnover","a":"Higher profits and lower turnover"}]},{"level":"C2","task":["Write a 120-word review of a documentary you saw."],"title":"A review of a documentary","script":"Narrator: The documentary follows three families displaced by rising sea levels in the Pacific. Its strength lies in intimate interviews rather than statistics, which makes the crisis tangible. However, the second half becomes repetitive, and the director\u0027s reluctance to discuss political solutions leaves the audience with sympathy but little direction. On balance, it is a moving, if imperfect, piece of filmmaking.","spec":"Listening · 5 вопросов + задание","takeaway":"Монолог: прослушайте и ответьте на вопросы.","genders":{"Narrator":"f"},"tasks":[{"q":"Who does the film follow?","e":"Three families displaced by rising sea levels","a":"Three families displaced by rising sea levels"},{"q":"What is its strength?","e":"Intimate interviews","a":"Intimate interviews"},{"q":"What is the weakness of the second half?","e":"It is repetitive","a":"It is repetitive"},{"q":"What does the director avoid?","e":"Political solutions","a":"Political solutions"},{"q":"What is the reviewer\u0027s overall verdict?","e":"Moving but imperfect","a":"Moving but imperfect"}]},{"level":"C2","task":["Where would you draw the line? Write 100 words."],"title":"A conversation about ethics in science","script":"Presenter: Should scientists be allowed to edit human genes?\nGuest: For treating serious inherited diseases, yes, under strict supervision. But editing for appearance or intelligence raises profound ethical issues.\nPresenter: Who decides where to draw the line?\nGuest: Ideally, an independent body combining scientists, ethicists and ordinary citizens.","spec":"Listening · 5 вопросов + задание","takeaway":"Диалог: прослушайте и ответьте на вопросы.","genders":{"Presenter":"f","Guest":"m"},"tasks":[{"q":"What is the question?","e":"Should scientists edit human genes","a":"Should scientists edit human genes"},{"q":"When is editing acceptable?","e":"To treat serious inherited diseases under supervision","a":"To treat serious inherited diseases under supervision"},{"q":"What is problematic?","e":"Editing for appearance or intelligence","a":"Editing for appearance or intelligence"},{"q":"Who should draw the line?","e":"An independent body","a":"An independent body"},{"q":"Who belongs to this body?","e":"Scientists, ethicists and citizens","a":"Scientists, ethicists and citizens"}]}];
